    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>ডেলিভারি নিয়ম: ঢাকার ভেতরে ৮০ টাকা, বাইরে ১৫০ টাকা, আর ২০০০ টাকার বেশি অর্ডারে ঢাকার ভেতরে ফ্রি। এই হিসাব চেকআউট, কার্ট ও অর্ডার-কনফার্মেশন—তিন জায়গায় কপি-পেস্ট করা। নিয়ম বদলালে তিন জায়গায় বদলাতে হয়, আর একটিতে ভুলে গেলে গ্রাহক তিন রকম দাম দেখেন।</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>parameter ও return সহ function লিখতে ও কল করতে পারবেন</li><li>if / else if / else এবং ===, >, &&, || দিয়ে সিদ্ধান্ত লিখতে পারবেন</li><li>arrow function সিনট্যাক্স পড়তে ও লিখতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 35 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/arrays-objects/">Arrays ও Objects</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>ফাংশন</strong> (<em lang="en">function</em>) একটি কাজকে নাম দেয় যাতে একবার লিখে বহুবার ব্যবহার করা যায়।</p><pre class="wgba-code" data-lang="javascript"><code>function deliveryCharge(insideDhaka, orderTotal) {   // parameter
  if (insideDhaka &amp;&amp; orderTotal &gt; 2000) {
    return 0;            // return: আউটপুট ফেরত, ফাংশন এখানেই শেষ
  } else if (insideDhaka) {
    return 80;
  } else {
    return 150;
  }
}
console.log(deliveryCharge(true, 2500));   // কল করা (argument দিয়ে) → 0</code></pre><div class="wgba-table-wrap"><table><caption>তুলনা ও যুক্তি অপারেটর</caption><thead><tr><th scope="col">অপারেটর</th><th scope="col">অর্থ</th><th scope="col">উদাহরণ → ফল</th></tr></thead><tbody><tr><td><code>===</code></td><td>মান ও টাইপ দুটোই সমান</td><td><code>5 === 5</code> → true, <code>5 === "5"</code> → false</td></tr><tr><td><code>!==</code></td><td>সমান নয়</td><td><code>"ঢাকা" !== "খুলনা"</code> → true</td></tr><tr><td><code>&gt; &lt; &gt;= &lt;=</code></td><td>বড়/ছোট</td><td><code>2500 > 2000</code> → true</td></tr><tr><td><code>&amp;&amp;</code></td><td>দুটোই সত্য হলে সত্য (AND)</td><td><code>true && false</code> → false</td></tr><tr><td><code>||</code></td><td>যেকোনো একটি সত্য হলে সত্য (OR)</td><td><code>true || false</code> → true</td></tr><tr><td><code>!</code></td><td>উল্টো (NOT)</td><td><code>!true</code> → false</td></tr></tbody></table></div><p><code>==</code> (দুটি সমান চিহ্ন) টাইপ রূপান্তর করে তুলনা করে (<code>5 == "5"</code> → true)—এটি বাগ লুকায়। এই কোর্সে সবসময় <code>===</code>।</p><p><strong>Arrow function:</strong> ছোট function লেখার সংক্ষিপ্ত রূপ। <code>const double = (x) => x * 2;</code> মানে “x নাও, x × 2 ফেরত দাও”। এক লাইনে থাকলে <code>return</code> লিখতে হয় না। একাধিক লাইনে <code>{ }</code> ও <code>return</code> লাগে।</p></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> Function হলো একটি রেসিপি: উপকরণ (parameter) দিলে খাবার (return) পাবেন। if/else হলো রেসিপির ভেতরের “যদি দুধ না থাকে তবে পানি দিন” নির্দেশ।</p><p><strong>কোথায় ভাঙে:</strong> রেসিপিতে উপকরণ ভুল দিলে রাঁধুনি বুঝতে পারেন। JavaScript function ভুল টাইপের argument পেলেও চুপচাপ চলবে—যেমন orderTotal-এ "2500" (string) দিলে <code>"2500" > 2000</code> রূপান্তর করে true দেয়, কিন্তু সবসময় এমন ভাগ্য হবে না।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>তিনটি ইনপুটে ফাংশন ট্রেস করি:</p><div class="wgba-table-wrap"><table><thead><tr><th scope="col">insideDhaka</th><th scope="col">orderTotal</th><th scope="col">প্রথম শর্ত (&&)</th><th scope="col">দ্বিতীয় শর্ত</th><th scope="col">ফল</th></tr></thead><tbody><tr><td>true</td><td>2500</td><td>true && true = true</td><td>—</td><td>0</td></tr><tr><td>true</td><td>1500</td><td>true && false = false</td><td>true</td><td>80</td></tr><tr><td>false</td><td>3000</td><td>false && … = false</td><td>false</td><td>150</td></tr></tbody></table></div><p>লক্ষ্য করুন: শর্তগুলো উপর থেকে নিচে পরীক্ষা হয়, প্রথম যেটি সত্য সেটির ভেতরের return চলে, বাকিগুলো আর দেখা হয় না। তাই ক্রম গুরুত্বপূর্ণ—“ফ্রি” শর্তটি “৮০” শর্তের আগে না থাকলে ফ্রি কখনো আসত না।</p></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><div class="wgba-note">এই রানারে <code>console.log</code> আউটপুট দেখায়। ব্রাউজারের DOM, নেটওয়ার্ক (<code>fetch</code>), টাইমার বা ফাইল এখানে নেই—ইচ্ছাকৃতভাবে। Ctrl/⌘ + Enter চাপলেও Run হয়।</div><h3>ডেলিভারি চার্জ ফাংশন — একটি বাগ আছে</h3><div class="wgba-playground-slot" data-exercise="ex-les-02-03-functions-conditions-1"><pre class="wgba-code"><code>// নিয়ম: ঢাকায় 80, বাইরে 150, ঢাকায় 2000-এর বেশি হলে ফ্রি
function deliveryCharge(insideDhaka, orderTotal) {
  if (insideDhaka) {
    return 80;
  } else if (insideDhaka &amp;&amp; orderTotal &gt; 2000) {
    return 0;
  } else {
    return 150;
  }
}

console.log(&quot;ঢাকা 2500:&quot;, deliveryCharge(true, 2500));   // 0 হওয়া উচিত
console.log(&quot;ঢাকা 1500:&quot;, deliveryCharge(true, 1500));   // 80
console.log(&quot;বাইরে 3000:&quot;, deliveryCharge(false, 3000)); // 150

// arrow function দিয়ে মোট দাম
const grandTotal = (insideDhaka, orderTotal) =&gt; orderTotal + deliveryCharge(insideDhaka, orderTotal);
console.log(&quot;মোট:&quot;, grandTotal(true, 1500));</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>function deliveryCharge(insideDhaka, orderTotal)</code>: দুটি parameter—কল করার সময় যে মান দেওয়া হয় (argument) সেগুলো এখানে বসে।</li><li><code>insideDhaka && orderTotal > 2000</code>: আগে <code>></code> হিসাব হয়, তারপর <code>&&</code>। দুটো সত্য হলেই পুরোটা সত্য।</li><li><code>return 0;</code>: মান ফেরত দিয়ে ফাংশন থেমে যায়—নিচের else if আর চলে না।</li><li><code>const grandTotal = (a, b) => ...</code>: arrow function, যেটি ভেতরে আরেকটি function কল করছে। function দিয়ে function বানানো স্বাভাবিক।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>হিসাব একটি function-এ থাকলে নিয়ম বদলাতে এক জায়গায় বদলাতে হয়, আর আলাদাভাবে পরীক্ষা করা যায় (সীমানা ২০০০, ২০০১)। পরের অধ্যায়ের সব গণিত—dot product, loss, softmax—ছোট ছোট function হিসেবে লিখব।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>function: parameter নেয়, return দেয়</li><li>শর্ত উপর থেকে নিচে; নির্দিষ্টটি আগে</li><li>সবসময় === ব্যবহার</li><li>arrow: (x) => x * 2</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>switch statement</li><li>default parameter ও rest parameter</li><li>function hoisting-এর নিয়ম</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>নতুন নিয়ম যোগ করুন: চট্টগ্রামে ১২০ টাকা। প্রথম parameter boolean-এর বদলে শহরের নাম (string) নিন: <code>deliveryCharge("চট্টগ্রাম", 1000)</code>। কোন শর্ত কোন ক্রমে রাখবেন?</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>সাধারণ শর্ত নির্দিষ্ট শর্তের আগে রাখা (এই পাঠের বাগ)</li><li>return না লিখে console.log দেওয়া—তখন ফাংশন undefined ফেরত দেয়</li><li>= (মান দেওয়া) আর === (তুলনা) গুলিয়ে ফেলা</li><li>সীমানার মান (ঠিক ২০০০) পরীক্ষা না করা</li></ul></section>
<section class="wgba-section" id="check"><h2>জ্ঞান যাচাই</h2><p>নিচের 3টি প্রশ্নের উত্তর দিয়ে “জমা দিন” চাপুন। স্কোর সার্ভারে যাচাই হয়; প্রতিটি উত্তরের পর কেন সঠিক বা ভুল তা দেখাবে। লগইন থাকলে ফল আপনার অগ্রগতিতে সংরক্ষিত হয়।</p></section>
