    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>অর্ডার সিস্টেম থেকে টেক্সট আসে <code>{"id":"ORD-17","status":"shipped"}</code>। কখনো কখনো ভাঙা টেক্সট আসে (<code>{"id":"ORD-18",</code>), আর পুরো পেজ crash করে। তার ওপর, সার্ভার উত্তর দিতে ২ সেকেন্ড নেয়—কোড কি এই সময় অন্য সব কাজ থামিয়ে বসে থাকবে?</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>JSON.stringify ও JSON.parse দিয়ে object ↔ টেক্সট রূপান্তর করতে পারবেন</li><li>try/catch দিয়ে ভাঙা ইনপুট নিরাপদে সামলাতে এবং throw দিয়ে নিজের এরর তৈরি করতে পারবেন</li><li>async function ও await দিয়ে Promise-ভিত্তিক কোড লিখতে এবং fixture বনাম আসল API-র পার্থক্য বলতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 40 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/loops-modules/">Loops, Modules ও Execution Flow</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>JSON</strong> (<em lang="en">JavaScript Object Notation</em>): object/array-কে টেক্সটে লেখার নিয়ম। key সবসময় ডাবল কোটেশনে; string, number, boolean, null, array, object চলে; function বা undefined চলে না।</p><pre class="wgba-code" data-lang="javascript"><code>const order = { id: &quot;ORD-17&quot;, items: 2, paid: true };
const text = JSON.stringify(order);   // object → টেক্সট
const back = JSON.parse(text);        // টেক্সট → object</code></pre><p><strong>এরর হ্যান্ডলিং</strong> (<em lang="en">error handling</em>): <code>JSON.parse</code> ভাঙা টেক্সট পেলে <em>exception</em> ছোড়ে (throw)। <code>try { … } catch (err) { … }</code> সেটি ধরে, যাতে প্রোগ্রাম থেমে না যায়। নিজেও <code>throw new Error("বার্তা")</code> দিয়ে এরর ছোড়া যায়—যেমন অর্ডার নম্বর খালি হলে।</p><p><strong>প্রমিস</strong> (<em lang="en">Promise</em>): এমন একটি মান যা “পরে আসবে”। <strong>async/await</strong> (<em lang="en">async/await</em>): <code>async function</code>-এর ভেতরে <code>await</code> লিখলে সেই Promise শেষ না হওয়া পর্যন্ত ওই function অপেক্ষা করে, কিন্তু বাকি প্রোগ্রাম আটকে থাকে না। async function নিজেও একটি Promise ফেরত দেয়।</p><div class="wgba-table-wrap"><table><caption>fixture বনাম আসল API</caption><thead><tr><th scope="col"></th><th scope="col">লোকাল fixture (এই পাঠ)</th><th scope="col">আসল নেটওয়ার্ক কল</th></tr></thead><tbody><tr><td>ডেটা কোথা থেকে</td><td>কোডের ভেতরে লেখা নমুনা</td><td>অন্য কম্পিউটারের সার্ভার</td></tr><tr><td>সময়</td><td>প্রায় তাৎক্ষণিক</td><td>মিলিসেকেন্ড থেকে সেকেন্ড; অনিশ্চিত</td></tr><tr><td>ব্যর্থতা</td><td>শুধু আমরা যা সিমুলেট করি</td><td>নেটওয়ার্ক বিচ্ছিন্ন, timeout, 500 এরর, rate limit</td></tr><tr><td>নিরাপত্তা</td><td>কোনো তথ্য বাইরে যায় না</td><td>API key, ব্যক্তিগত ডেটা সাবধানে সামলাতে হয়</td></tr></tbody></table></div><p>এই রানারে <code>fetch</code> নেই—ইচ্ছাকৃত। তাই আমরা <code>Promise.resolve(...)</code> দিয়ে fixture বানাব। কোডের কাঠামো (async/await, try/catch) আসল API-তেও একই থাকবে; অধ্যায় ১০-এ timeout ও retry যোগ করব।</p></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> async/await হলো রেস্তোরাঁয় অর্ডার দিয়ে টোকেন নেওয়া: খাবার তৈরি হওয়া পর্যন্ত আপনি অন্য কাজ করতে পারেন, টোকেন ডাকলে (await শেষ) খাবার নেন। try/catch হলো “খাবার শেষ হয়ে গেলে বিকল্প অর্ডার” পরিকল্পনা।</p><p><strong>কোথায় ভাঙে:</strong> রেস্তোরাঁ সাধারণত খাবার দেয়ই; নেটওয়ার্ক কল কখনো উত্তরই না দিতে পারে (চিরকাল ঝুলে থাকা)—তাই বাস্তবে timeout লাগে, যা এই উপমায় নেই।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>ধাপে ধাপে: fixture থেকে অর্ডার আনা, JSON parse করা, ভুল সামলানো।</p><pre class="wgba-code" data-lang="javascript"><code>const fixtures = {
  &quot;ORD-17&quot;: \'{&quot;id&quot;:&quot;ORD-17&quot;,&quot;status&quot;:&quot;shipped&quot;}\',
  &quot;ORD-18&quot;: \'{&quot;id&quot;:&quot;ORD-18&quot;,\',          // ইচ্ছাকৃত ভাঙা
};
function fakeFetchOrder(id) {          // আসল API-র নকল
  return Promise.resolve(fixtures[id]);
}
async function getStatus(id) {
  const text = await fakeFetchOrder(id);
  try {
    return JSON.parse(text).status;
  } catch (err) {
    return &quot;ডেটা ভাঙা: &quot; + err.name;
  }
}</code></pre><ol><li><code>getStatus("ORD-17")</code> কল → await fixture-এর টেক্সট পায় → parse → "shipped"।</li><li><code>getStatus("ORD-18")</code> → parse ব্যর্থ → SyntaxError ধরা পড়ে → "ডেটা ভাঙা: SyntaxError"।</li><li><code>getStatus("ORD-99")</code> → fixture-এ নেই → text = undefined → <code>JSON.parse(undefined)</code>-ও SyntaxError। ভালো কোডে আগেই “অর্ডার পাওয়া যায়নি” বলা উচিত।</li></ol></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><div class="wgba-note">এই রানারে <code>console.log</code> আউটপুট দেখায়। ব্রাউজারের DOM, নেটওয়ার্ক (<code>fetch</code>), টাইমার বা ফাইল এখানে নেই—ইচ্ছাকৃতভাবে। Ctrl/⌘ + Enter চাপলেও Run হয়।</div><h3>fixture দিয়ে async/await ও এরর</h3><div class="wgba-playground-slot" data-exercise="ex-les-02-05-json-async-1"><pre class="wgba-code"><code>// লোকাল fixture — আসল নেটওয়ার্ক নয়
const fixtures = {
  &quot;ORD-17&quot;: \'{&quot;id&quot;:&quot;ORD-17&quot;,&quot;status&quot;:&quot;shipped&quot;,&quot;items&quot;:2}\',
  &quot;ORD-18&quot;: \'{&quot;id&quot;:&quot;ORD-18&quot;,\',
};

function fakeFetchOrder(id) {
  if (!id) {
    return Promise.reject(new Error(&quot;অর্ডার নম্বর খালি&quot;));
  }
  return Promise.resolve(fixtures[id]);
}

async function getStatus(id) {
  try {
    const text = await fakeFetchOrder(id);
    if (text === undefined) {
      throw new Error(&quot;অর্ডার পাওয়া যায়নি: &quot; + id);
    }
    const order = JSON.parse(text);
    return order.id + &quot; → &quot; + order.status;
  } catch (err) {
    return &quot;সমস্যা (&quot; + err.name + &quot;): &quot; + err.message;
  }
}

async function main() {
  console.log(&quot;শুরু&quot;);
  for (const id of [&quot;ORD-17&quot;, &quot;ORD-18&quot;, &quot;ORD-99&quot;, &quot;&quot;]) {
    console.log(await getStatus(id));
  }
  console.log(&quot;JSON আবার:&quot;, JSON.stringify({ id: &quot;ORD-17&quot;, ok: true }));
}

main();
console.log(&quot;main() কল হয়েছে — কিন্তু ফল এখনও আসেনি!&quot;);</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>Promise.reject(new Error(...))</code>: ব্যর্থ Promise—await করলে এটি exception হিসেবে ছোড়ে, তাই catch ধরে।</li><li><code>const text = await fakeFetchOrder(id)</code>: Promise-এর ভেতরের মান বের করে; ব্যর্থ হলে throw।</li><li><code>throw new Error("অর্ডার পাওয়া যায়নি")</code>: নিজের এরর; বার্তাটি err.message-এ যায়, ধরনটি err.name ("Error")।</li><li><code>err.name</code>: JSON ভাঙলে "SyntaxError", নিজের হলে "Error"—এভাবে ধরন আলাদা করা যায়।</li><li>শেষ লাইনটি main-এর ভেতরের await-গুলোর আগে ছাপা হয়—async কাজ “পরে” শেষ হয়, এটাই execution flow।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>LLM API-র উত্তর (অধ্যায় ১০) JSON-এ আসে এবং কখনো ভাঙা বা স্কিমার বাইরে থাকে; নেটওয়ার্ক কল async এবং ব্যর্থ হতে পারে। এখনই try/catch ও await-এর অভ্যাস হলে পরের অধ্যায়ে শুধু timeout/retry যোগ করতে হবে।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>JSON = টেক্সট; parse করে object, stringify করে টেক্সট</li><li>বাইরের ডেটা parse করতে সবসময় try/catch</li><li>await শুধু async function-এর ভেতরে</li><li>fixture ≠ আসল API: সময়, ব্যর্থতা, নিরাপত্তা আলাদা</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>Promise.all, Promise.race</li><li>event loop-এর microtask/macrotask বিস্তারিত</li><li>fetch API-র সব অপশন</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>fixtures-এ <code>"ORD-19": \'{"id":"ORD-19"}\'</code> যোগ করুন (status নেই)। আউটপুটে কী আসে? “ORD-19 → undefined” দেখালে সেটি কি ব্যবহারকারীর জন্য ভালো বার্তা? কোড বদলে “স্ট্যাটাস জানা নেই” দেখান।</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>JSON-এ সিঙ্গেল কোটেশনে key লেখা—{\'id\': 1} বৈধ JSON নয়</li><li>await ছাড়া async function কল করে ফল ব্যবহার করা (Promise পাবেন, মান নয়)</li><li>catch-এ এরর চুপচাপ গিলে ফেলা, কিছু না জানানো</li><li>fixture-এ কাজ করলেই ধরে নেওয়া আসল API-তেও করবে</li></ul></section>
<section class="wgba-section" id="check"><h2>জ্ঞান যাচাই</h2><p>নিচের 3টি প্রশ্নের উত্তর দিয়ে “জমা দিন” চাপুন। স্কোর সার্ভারে যাচাই হয়; প্রতিটি উত্তরের পর কেন সঠিক বা ভুল তা দেখাবে। লগইন থাকলে ফল আপনার অগ্রগতিতে সংরক্ষিত হয়।</p></section>
<section class="wgba-section" id="recap"><h2>সংক্ষেপে মনে রাখুন</h2><ul><li>JSON: ডেটার সাধারণ ভাষা</li><li>try/catch/throw: ব্যর্থতা নিয়ন্ত্রিতভাবে সামলানো</li><li>async/await: অপেক্ষার কাজ, প্রোগ্রাম আটকায় না</li><li>fixture দিয়ে শিখি, আসলের পার্থক্য মনে রাখি</li></ul></section>
