<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p>পাইপলাইন (ইনপুট → রূপান্তর → আউটপুট):</p><ol><li><strong>Normalize:</strong> ছোট হাতের অক্ষর, বিরামচিহ্ন সরানো, অতিরিক্ত স্পেস বাদ। “ORD-17?” → “ord-17”।</li><li><strong>Extract:</strong> অর্ডার নম্বর খোঁজা (প্যাটার্ন: ord- তারপর অঙ্ক)।</li><li><strong>Score intents:</strong> প্রতিটি intent-এর কীওয়ার্ড তালিকা; মেসেজে যতগুলো মেলে ততো স্কোর।</li><li><strong>Decide:</strong> সর্বোচ্চ স্কোর নির্দিষ্ট সীমার (threshold) কম হলে বা দুটি intent সমান হলে → fallback (মানুষের কাছে)।</li><li><strong>Act:</strong> status intent ও অর্ডার নম্বর থাকলে fixture থেকে স্ট্যাটাস আনা (async)।</li><li><strong>Trace:</strong> প্রতিটি ধাপের মান ফেরত দেওয়া যাতে কেন এই উত্তর তা দেখা যায়।</li></ol><p><strong>নতুন সিনট্যাক্স:</strong> <code>/ord-(\\d+)/</code> হলো একটি <em>regular expression</em>—টেক্সটে প্যাটার্ন খোঁজার ছোট ভাষা। <code>\\d+</code> মানে “এক বা একাধিক অঙ্ক”। <code>text.match(regex)</code> মিললে একটি array দেয়, না মিললে null। এখানে শুধু এই একটি প্যাটার্ন ব্যবহার করব।</p><div class="wgba-note wgba-note-warn">ডেলিভারি চার্জ ও ফেরত নীতির সংখ্যাগুলো এই প্রজেক্টের জন্য উদাহরণ। আসল দোকানে এগুলো দোকানের নিজস্ব নীতি থেকে আসবে, কোডে হার্ডকোড করা অনুমান থেকে নয়।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> অ্যাসিস্ট্যান্ট হলো রাতের পাহারাদার যার হাতে একটি নির্দেশিকা-কার্ড: “কেউ ডেলিভারি চার্জ জিজ্ঞেস করলে এটা বলো; বুঝতে না পারলে লিখে রাখো, সকালে ম্যানেজার দেখবেন।”</p><p><strong>কোথায় ভাঙে:</strong> পাহারাদার নতুন ধরনের প্রশ্ন শুনে বুদ্ধি খাটাতে পারেন; আমাদের অ্যাসিস্ট্যান্ট কার্ডের বাইরে এক পা-ও যায় না—“পাঠানোর খরচ” আর “ডেলিভারি চার্জ” একই জিনিস তা সে জানে না যদি না কীওয়ার্ড যোগ করা হয়।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>মেসেজ: <q>ORD-17 এর ডেলিভারি স্ট্যাটাস কী?</q></p><div class="wgba-table-wrap"><table><caption>একটি মেসেজের সম্পূর্ণ ট্রেস</caption><thead><tr><th scope="col">ধাপ</th><th scope="col">মান</th></tr></thead><tbody><tr><td>normalize</td><td>"ord-17 এর ডেলিভারি স্ট্যাটাস কী"</td></tr><tr><td>extract</td><td>orderId = "ORD-17"</td></tr><tr><td>score</td><td>status: ২ (স্ট্যাটাস, ord-), shipping: ১ (ডেলিভারি), returns: ০</td></tr><tr><td>decide</td><td>সর্বোচ্চ status = ২ ≥ threshold ১, দ্বিতীয় ১ → টাই নয় → status</td></tr><tr><td>act</td><td>fixture → "shipped"</td></tr><tr><td>reply</td><td>“অর্ডার ORD-17 এর অবস্থা: পাঠানো হয়েছে”</td></tr></tbody></table></div><p>লক্ষ্য করুন “ডেলিভারি” শব্দ shipping-এর দিকেও টেনেছিল। ট্রেস না দেখলে আমরা জানতাম না সিদ্ধান্ত কত কাছাকাছি ছিল।</p></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><div class="wgba-note">এই রানারে <code>console.log</code> আউটপুট দেখায়। ব্রাউজারের DOM, নেটওয়ার্ক (<code>fetch</code>), টাইমার বা ফাইল এখানে নেই—ইচ্ছাকৃতভাবে। Ctrl/⌘ + Enter চাপলেও Run হয়।</div><p><strong>প্রজেক্ট মানদণ্ড:</strong> (১) প্রদত্ত ৮টি পরীক্ষা মেসেজের প্রতিটিতে ট্রেসসহ উত্তর, (২) অন্তত তিনটি ব্যর্থতার কারণ নিজের ভাষায় লেখা, (৩) একটি উন্নতি (নতুন কীওয়ার্ড বা নিয়ম) যোগ করে আগের সঠিক উত্তরগুলো ভাঙেনি তা দেখানো।</p><h3>প্রজেক্ট: নিয়মভিত্তিক সাপোর্ট অ্যাসিস্ট্যান্ট (AI মডেল নয়)</h3><div class="wgba-playground-slot" data-exercise="ex-les-02-07-project-support-bot-1"><pre class="wgba-code"><code>// ---- কনফিগারেশন (উদাহরণ নীতি) ----
const INTENTS = {
  shipping: { keywords: [&quot;ডেলিভারি&quot;, &quot;চার্জ&quot;, &quot;শিপিং&quot;, &quot;কত দিন&quot;], reply: &quot;ঢাকায় ডেলিভারি ৮০ টাকা, ঢাকার বাইরে ১৫০ টাকা।&quot; },
  returns:  { keywords: [&quot;ফেরত&quot;, &quot;রিটার্ন&quot;, &quot;বদল&quot;], reply: &quot;পণ্য হাতে পাওয়ার ৩ দিনের মধ্যে ফেরতের অনুরোধ করা যায়।&quot; },
  status:   { keywords: [&quot;স্ট্যাটাস&quot;, &quot;কোথায়&quot;, &quot;ord-&quot;, &quot;পৌঁছাবে&quot;], reply: null },
};
const THRESHOLD = 1;
const FALLBACK = &quot;দুঃখিত, নিশ্চিত হতে পারছি না। একজন প্রতিনিধি সকালে উত্তর দেবেন।&quot;;

// ---- লোকাল fixture (আসল অর্ডার সিস্টেম নয়) ----
const ORDERS = { &quot;ORD-17&quot;: &quot;shipped&quot;, &quot;ORD-21&quot;: &quot;processing&quot; };
const STATUS_BN = { shipped: &quot;পাঠানো হয়েছে&quot;, processing: &quot;প্রস্তুত হচ্ছে&quot; };
const fakeOrderApi = (id) =&gt; Promise.resolve(ORDERS[id]);

// ---- পাইপলাইন ----
function normalize(text) {
  return text.toLowerCase().replace(/[?!,।]/g, &quot; &quot;).replace(/\\s+/g, &quot; &quot;).trim();
}

function extractOrderId(text) {
  const m = text.match(/ord-(\\d+)/);
  return m ? &quot;ORD-&quot; + m[1] : null;
}

function scoreIntents(text) {
  const scores = {};
  for (const name of Object.keys(INTENTS)) {
    scores[name] = INTENTS[name].keywords.filter((k) =&gt; text.includes(k)).length;
  }
  return scores;
}

function decide(scores) {
  const ranked = Object.entries(scores).sort((a, b) =&gt; b[1] - a[1]);
  const [best, second] = ranked;
  if (best[1] &lt; THRESHOLD) return { intent: null, why: &quot;কোনো কীওয়ার্ড মেলেনি&quot; };
  if (best[1] === second[1]) return { intent: null, why: &quot;টাই: &quot; + best[0] + &quot; = &quot; + second[0] };
  return { intent: best[0], why: best[0] + &quot; স্কোর &quot; + best[1] };
}

async function respond(message) {
  const text = normalize(message);
  const orderId = extractOrderId(text);
  const scores = scoreIntents(text);
  const decision = decide(scores);
  let reply = FALLBACK;
  if (decision.intent === &quot;status&quot;) {
    if (!orderId) {
      reply = &quot;অর্ডার নম্বর (যেমন ORD-17) দিলে স্ট্যাটাস দেখাতে পারব।&quot;;
    } else {
      const status = await fakeOrderApi(orderId);
      reply = status ? &quot;অর্ডার &quot; + orderId + &quot; এর অবস্থা: &quot; + STATUS_BN[status] : &quot;অর্ডার &quot; + orderId + &quot; খুঁজে পাইনি।&quot;;
    }
  } else if (decision.intent) {
    reply = INTENTS[decision.intent].reply;
  }
  return { message, text, orderId, scores, decision: decision.why, reply };
}

// ---- পরীক্ষা ----
const tests = [
  &quot;ORD-17 এর ডেলিভারি স্ট্যাটাস কী?&quot;,
  &quot;ঢাকার বাইরে ডেলিভারি চার্জ কত?&quot;,
  &quot;পণ্য ফেরত দিতে চাই&quot;,
  &quot;ORD-99 কোথায়?&quot;,
  &quot;আমার পার্সেল কবে আসবে&quot;,
  &quot;ফেরত চাই না, শুধু ডেলিভারি কবে বলুন&quot;,
  &quot;delivery charge koto?&quot;,
  &quot;ধন্যবাদ!&quot;,
];

async function main() {
  for (const t of tests) {
    const r = await respond(t);
    console.log(&quot;▶ &quot; + r.message);
    console.log(&quot;   scores=&quot; + JSON.stringify(r.scores) + &quot; | &quot; + r.decision + &quot; | order=&quot; + r.orderId);
    console.log(&quot;   ↳ &quot; + r.reply);
  }
}
main();</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>normalize</code>: দুটি regex replace—প্রথমটি বিরামচিহ্নকে স্পেস বানায়, দ্বিতীয়টি (<code>/\\s+/g</code>) একাধিক স্পেসকে এক স্পেস। <code>g</code> মানে “সব জায়গায়”।</li><li><code>extractOrderId</code>: <code>m[1]</code> হলো বন্ধনীর ভেতরের অংশ (অঙ্কগুলো)। না মিললে null—পরে if দিয়ে যাচাই।</li><li><code>scoreIntents</code>: প্রতিটি intent-এর জন্য কতটি কীওয়ার্ড টেক্সটে আছে (<code>filter(...).length</code>)।</li><li><code>Object.entries(scores).sort(...)</code>: [নাম, স্কোর] জোড়ার array, বড় থেকে ছোট সাজানো। <code>const [best, second] = ranked</code> প্রথম দুটি বের করে।</li><li><code>decide</code>: threshold ও টাই—দুই অনিশ্চয়তায় fallback। এটি “ভুল তথ্যের চেয়ে জানি না ভালো” নীতির কোড রূপ।</li><li><code>respond</code> একটি পুরো ট্রেস object ফেরত দেয়—শুধু উত্তর নয়। পরে মূল্যায়ন (অধ্যায় ১২) এই ট্রেস দিয়েই হবে।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>প্রতিটি ধাপ আলাদা function হওয়ায় আলাদাভাবে পরীক্ষা ও বদলানো যায়। Fallback-কে প্রথম শ্রেণির ফল হিসেবে রাখা হয়েছে কারণ সাপোর্ট সিস্টেমে আত্মবিশ্বাসী ভুল উত্তর গ্রাহকের আস্থা নষ্ট করে। ট্রেস দেখানো হয়েছে যাতে কোনো সিদ্ধান্ত “কালো বাক্স” না থাকে।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>পাইপলাইন: normalize → extract → score → decide → act</li><li>অনিশ্চিত হলে fallback—threshold ও টাই</li><li>ট্রেস ছাড়া ব্যর্থতা বোঝা যায় না</li><li>নিয়মভিত্তিক সিস্টেম অর্থ নয়, শব্দ মেলায়</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>regular expression-এর বাকি সিনট্যাক্স</li><li>Object.entries/sort-এর সব বিকল্প</li><li>বাস্তব চ্যাট প্ল্যাটফর্মে সংযোগ</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>তিনটি পরিবর্তন একটি একটি করে করুন এবং প্রতিবার সব ৮টি পরীক্ষা দেখুন: (১) status-এ "কবে আসবে" যোগ, (২) shipping-এ "delivery", "charge" যোগ, (৩) "না" শব্দ থাকলে returns স্কোর থেকে ১ বাদ। কোন পরিবর্তন অন্য কোনো উত্তর ভেঙে দিল? এটিই regression—অধ্যায় ১২-এ এর পরীক্ষা স্বয়ংক্রিয় করব।</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>একটি মেসেজ ঠিক করতে গিয়ে অন্যগুলো পরীক্ষা না করা (regression)</li><li>fallback না রেখে সবসময় কোনো না কোনো উত্তর দেওয়া</li><li>fixture-এর অর্ডার ডেটাকে আসল ধরে নেওয়া</li><li>কীওয়ার্ড তালিকা বাড়াতে বাড়াতে নিয়ম পরস্পরবিরোধী করে ফেলা</li></ul></section>
<details class="wgba-disclose"><summary>সমাধান ও ব্যাখ্যা</summary><div><p>প্রত্যাশিত ব্যর্থতাগুলো: “আমার পার্সেল কবে আসবে” — কোনো কীওয়ার্ড নেই (শব্দভাণ্ডারের ফাঁক)। “ফেরত চাই না…” — shipping ও returns টাই, কারণ নিয়ম নেতিবাচকতা বোঝে না। “delivery charge koto?” — বাংলিশ ইনপুট, তালিকায় নেই (distribution shift)। “ধন্যবাদ!” — fallback ঠিক আছে, কিন্তু আদর্শভাবে একটি ভদ্র উত্তর দেওয়া যেত। প্রতিটি সমাধানে নতুন নিয়ম লাগে, আর নিয়ম বাড়লে পারস্পরিক সংঘর্ষ বাড়ে—এটিই শেখা মডেলের দিকে যাওয়ার কারণ। কিন্তু মনে রাখুন, শেখা মডেলেরও fallback ও ট্রেস লাগবে।</p></div></details>
<section class="wgba-section" id="check"><h2>জ্ঞান যাচাই</h2><p>নিচের 4টি প্রশ্নের উত্তর দিয়ে “জমা দিন” চাপুন। স্কোর সার্ভারে যাচাই হয়; প্রতিটি উত্তরের পর কেন সঠিক বা ভুল তা দেখাবে। লগইন থাকলে ফল আপনার অগ্রগতিতে সংরক্ষিত হয়।</p></section>
<section class="wgba-section" id="recap"><h2>সংক্ষেপে মনে রাখুন</h2><ul><li>সম্পূর্ণ পাইপলাইন ট্রেসসহ বানালেন</li><li>নিয়মভিত্তিক সিস্টেমের তিন ব্যর্থতা: শব্দভাণ্ডারের ফাঁক, নেতিবাচকতা, ভিন্ন লিপি</li><li>fallback ও regression পরীক্ষা যেকোনো AI সিস্টেমেও লাগবে</li></ul></section>
<section class="wgba-section" id="next"><h2>পরবর্তী পাঠ</h2><p>নিয়মের সীমা দেখলেন। শেখা মডেল বুঝতে প্রথমে লাগবে গণিত—অধ্যায় ৩ (লগইন প্রয়োজন, বিনামূল্যে): <a href="/ai-academy/lesson/scalar-vector/">Scalar, Vector ও Dimension</a></p></section>
<section class="wgba-section" id="sources"><h2>সূত্র ও যাচাই</h2><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Regular_expressions" rel="noopener">MDN — Regular expressions guide</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/async_function" rel="noopener">MDN — async function</a></li><li><a href="https://web.stanford.edu/~jurafsky/slp3/" rel="noopener">Jurafsky &amp; Martin — Speech and Language Processing (3rd ed. draft)</a></li></ul><p class="wgba-meta">যাচাইয়ের তারিখ: 2026-10-19; লেখক: Muhibbullah Ansary। এই পাঠের 1টি JavaScript উদাহরণ বিল্ডের সময় সাইটের একই QuickJS রানারে চালানো হয়েছে এবং প্রত্যাশিত আউটপুট মিলেছে; সংখ্যাগত ফলাফল আলাদা assertion দিয়ে (floating-point tolerance সহ) পরীক্ষিত। এই পাঠের ডেটা/উদাহরণ শেখানোর জন্য তৈরি সিন্থেটিক ডেটা—বাস্তব কোনো দোকান বা গ্রাহকের নয়। স্বাধীন বিশেষজ্ঞ রিভিউ এখনও হয়নি; ভুল পেলে যোগাযোগ পাতায় জানান।</p></section>',
